class TreeNode {
  constructor(val) {
    this.val = val;
    this.left = null;
    this.right = null;
  }
}

function isBalanced(root) {
  let balanced = true;
  const height = (node) => {
    if (!node) return 0;
    const lh = height(node.left);
    const rh = height(node.right);
    if (Math.abs(lh - rh) > 1) balanced = false;
    return 1 + Math.max(lh, rh);
  };
  height(root);
  return balanced;
}

